// A date-time serialises to the canonical wire form in every JSON position, not
// only on the parameter path: a bare value, a pointer, a slice and a map.
func TestBhvSerializationobject151_ObjectSerializer_DateTimeJSON_CanonicalInEveryPosition(t *testing.T) {
	t.Parallel()
	ts := models.DateTime(time.Date(2024, 1, 1, 12, 30, 45, 123456789, time.UTC))
	const want = "2024-01-01T12:30:45.123+00:00"
	payload := struct {
		Direct  models.DateTime            `json:"direct"`
		Pointer *models.DateTime           `json:"pointer"`
		Slice   []models.DateTime          `json:"slice"`
		Map     map[string]models.DateTime `json:"map"`
	}{ts, &ts, []models.DateTime{ts}, map[string]models.DateTime{"k": ts}}
	data, err := serialize(payload)
	if err != nil {
		t.Fatalf("serialize failed: %v", err)
	}
	if got := strings.Count(string(data), want); got != 4 {
		t.Errorf("expected the canonical %q in all 4 positions, found %d in %s", want, got, data)
	}
	if strings.Contains(string(data), "Z\"") {
		t.Errorf("a UTC value must never render the Z designator: %s", data)
	}
}

// Reading is lenient: Z or a numeric offset, and a 0/3/6/9-digit fraction.
func TestObjectSerializer_DateTimeJSON_UnmarshalIsLenient(t *testing.T) {
	t.Parallel()
	inputs := []string{
		"2024-01-01T12:30:45Z",
		"2024-01-01T12:30:45+00:00",
		"2024-01-01T12:30:45.123Z",
		"2024-01-01T12:30:45.123000+00:00",
		"2024-01-01T12:30:45.123000000Z",
	}
	for _, in := range inputs {
		var got models.DateTime
		if err := deserialize([]byte(`"`+in+`"`), &got); err != nil {
			t.Errorf("%q: unexpected error: %v", in, err)
			continue
		}
		want, _ := time.Parse(time.RFC3339Nano, in)
		if !got.Time().Equal(want) {
			t.Errorf("%q: got %v, want %v", in, got.Time(), want)
		}
	}
	var bad models.DateTime
	if err := deserialize([]byte(`"not-a-date"`), &bad); err == nil {
		t.Error("expected an error for a malformed date-time")
	}
}

