/* requireNullElementError checks that err is the *SerializationError a null
 * element of a non-nullable container produces. */
func requireNullElementError(t *testing.T, err error) {
	t.Helper()
	var serErr *SerializationError
	if !errors.As(err, &serErr) {
		t.Fatalf("expected a *SerializationError for a null element, got %T: %v", err, err)
	}
}

